  ["89580560cb9936bc"] = { "Mentre cercava altri druidi in letargo, Malfurion trovò l'antica prigione sotterranea in cui aveva incatenato suo fratello, Illidan. Convinta che Illidan li avrebbe aiutati contro la Legione, Tyrande lo liberò. Benché Illidan li avesse aiutati per un certo tempo, alla fine fuggì per perseguire i propri interessi.", "." },
  ["8971bc0ff77d91e9"] = { "Quel giorno ci spingemmo a sud, seguendo alcune tracce fresche di pantera. Presto raggiungemmo un burrone attraversato da un enorme ponte di corde. Alla vista di quella meraviglia d'ingegneria non potei fare a meno di pensare agli scritti descrittivi di Brann su questa regione. Così spesso si dava per scontato che i troll nativi fossero una razza primitiva e ignorante, eppure, osservando la maestria con cui era costruito il ponte, potei riconoscere l'abilità con cui i costruttori troll avevano compiuto un'impresa apparentemente impossibile.", "." },
  ["8982bdb56880cbc7"] = { "CONGRATULAZIONI!\n\nOra il fantastico tartasniffo è tuo, e puoi esserne fiero! Anche se è una creatura timida, siamo certi che troverai adorabili la morbida dolcezza e le incredibili capacità olfattive del tuo nuovo animale.\n\nNelle pagine seguenti troverai informazioni sul tuo tartasniffo riguardo a:\n\n1. Alimentazione e cura\n2. Comportamento eccentrico (e adorabile)\n3. Uso del brevettato ⟦Snufflenose Command Stick=Vincastro per Tartasniffo⟧(tm)\n\nAncora congratulazioni. Non ti deluderà,\n\n-Marwig Rustbolt\nTitolare, Snuff Inc.", "." },
  ["898eb941492eb5f6"] = { "Simone the Seductress:\n\nTroverai Simone a contaminare il ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Non farti ingannare dal suo travestimento. Avvicinati con cautela e sfidala a battaglia.", "." },
